pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Anything below the smallest plausible item (1..100, but conservatively < 20)
    // is nearly wasted capacity; penalize it hard.
    if post_residual < 20 {
        score += 90.0 * (1.0 - (post_residual as f64) / 20.0);
    } else if post_residual < 35 {
        score += 15.0;
    }

    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space pressure grows with stream progression.
    let progress = step_index as f64 / total_items as f64;
    score += 25.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // Open-bins pressure: with many bins open, prefer filling existing ones.
    score += 3.0 * open_bins_count as f64 * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit the resulting gap, mild penalty for stranding.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Mean-residual coupling: penalize creating a residual far below the mean
    // (fragmenting relative to the fleet state).
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score += 0.15 * diff;
    }

    // New-bin candidate calibration: an empty bin has large post_residual,
    // which is naturally unattractive; add a mild constant bias so we only
    // open new bins when the resulting score beats poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

