pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on post-residual (prefer tight fits aggressively)
    score = score * score / (bin_capacity as f64) + post_residual as f64 * 0.5;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // chain completion
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportionally for small slack after next item
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize large leftover dead space
            let dead = post_residual as f64;
            score += dead * 0.8;
        }
    }

    // Compare residual against mean residual: prefer bins with below-average residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it attractive only when it enables good future packing
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if next_item_size > 0 && next_item_size as f64 > item_size as f64 * 1.2 {
            // big item coming: opening fresh bin is reasonable
            score -= 250.0 * progress;
        } else {
            // default: discourage opening new bins when open bins fit
            score += 150.0 + 50.0 * (open_bins_count as f64);
        }
    }

    // Early stream: be more open to new bins to build structure
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 30.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A residual gap is "dead" if it cannot hold even the smallest plausible item.
    if post_residual > 0 {
        let min_gap = 10u32.min(bin_capacity);
        if post_residual < min_gap {
            score += 60.0 * (min_gap - post_residual) as f64;
        }
        // Penalize gaps that are small relative to typical item sizes (10..80 range),
        // scaled by stream progress (later in stream => tighter discipline).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let unusable_zone = 20u32; // gaps below 20 rarely useful
        if post_residual < unusable_zone {
            score += (unusable_zone - post_residual) as f64 * (25.0 + 35.0 * progress);
        }
        // Reward near-perfect fits strongly.
        if post_residual == 0 {
            score -= 40.0;
        } else if post_residual <= 5 {
            score -= 15.0;
        }
    }

    // Perfect-fit bonus when the NEXT item exactly fills the leftover gap.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 55.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the fit is mediocre.
    let open_pressure = open_bins_count as f64;
    let fit_quality = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 1.0 };
    score += open_pressure * (1.0 - fit_quality) * 4.0;

    // Discourage bins far below the mean residual (wasteful picks), mildly.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate handling: an empty bin is attractive only when the current item
    // is large and would leave a large, reusable gap elsewhere; otherwise keep bins tight.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are already open
        // (amortization) or when the item is big.
        let big_item_bonus = item_size as f64 / bin_capacity as f64;
        score += 18.0 - 10.0 * big_item_bonus;
        if open_bins_count > 0 {
            score += 6.0 * (open_bins_count as f64).ln();
        }
        // If no open bin fits well (this is the only fitting candidate), opening a new
        // bin is fine — reduce the penalty.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residuals that are too small to hold the smallest plausible item (<=10)
    // are pure waste; penalize them heavily with a superlinear term.
    if post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual <= 20 {
        // Small but potentially usable gaps: mild penalty proportional to tightness
        score += 6.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    } else {
        // Larger residual space is valuable; reward keeping big residuals
        score -= 0.05 * post_residual as f64;
    }

    // --- Reward exact / near-exact fits ---
    if post_residual == 0 {
        score -= 25.0; // perfect fill is ideal
    } else if post_residual <= 5 {
        score -= 10.0; // near-perfect fill
    }

    // --- Open-bins pressure: discourage spreading across many bins ---
    // When many bins are open, prefer bins with tighter fits (lower post_residual
    // already does this); add pressure to close bins rather than open new ones.
    let open_pressure = open_bins_count as f64 * 0.3;
    score += open_pressure * (1.0 - post_residual as f64 / bin_capacity as f64);

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- Lookahead: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0; // next item still fits: chain continues
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only if current placements would leave
        // big dead space; otherwise penalize opening new bins mildly.
        let mean_res = mean_residual;
        if post_residual > mean_res {
            score += 15.0; // new bin would be looser than average open bin
        } else {
            score -= 5.0; // fresh bin keeps large usable residual
        }
        // Late in the stream, avoid opening new bins for small gains
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // --- Mean residual alignment: prefer bins whose residual is below average
    // (tighter bins), encouraging consolidation.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

