pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post_residual (tight fit)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more; early on, residual flexibility is fine.
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (0.5 + 2.0 * progress) * cap;
    score += coupling;

    // Penalize large dead space relative to item size (non-linear)
    if it > 0.0 {
        let ratio = pr / it;
        score += ratio * ratio * (1.0 + progress);
    }

    // Reward tight fits: subtract when post_residual is small relative to capacity
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 10.0 * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // slight penalty spread over many options
        score += 2.0 * ((fitting_bins_count as f64 - 1.0).ln() + 1.0);
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (nx - pr).abs() < 1.0 {
            score -= 20.0;
        } else if nx <= pr {
            score -= 5.0 * (1.0 - (pr - nx) / cap);
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 3.0 * ((nx - pr) / cap);
        }
    }

    // New-bin candidate handling: make empty bin attractive only when current bin
    // fit is poor, via smooth comparison against mean_residual.
    if bin_residual == bin_capacity {
        // neutral baseline scaled by mean residual pressure
        score = mean_residual * (0.6 + 0.4 * progress) + 5.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose residual falls into
    // "small dead-space" classes are rewarded (waste is bounded).
    let dead = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: extremely desirable.
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    } else {
        // Penalize residuals in awkward mid-range classes via modulo structure.
        let class = post_residual % 10;
        let decade = post_residual / 10;
        // Mid-class residuals (3..7) are hardest to fill later.
        if class >= 3 && class <= 7 {
            score += (7 - class) as f64 * 1.5;
        } else {
            score -= 2.0;
        }
        // Large residuals are okay only early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if decade >= 4 {
            score += progress * 10.0;
        }
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this bin strongly (chaining placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 + slack * 0.05;
        // Extra reward if the next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize if this creates stranded space.
        score += (next_item_size as f64 - post_residual as f64).min(15.0) * 0.3;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to mean residual (poor fit elsewhere) or few bins are open.
    if bin_residual == bin_capacity {
        let tight_fit = mean_residual < item_size as f64;
        let early = step_index < 4 || open_bins_count == 0;
        if tight_fit || early {
            score -= 5.0;
        } else {
            score += 15.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins is better.
    score += (open_bins_count as f64).ln().max(0.0) * 0.8;

    // Prefer bins whose residual is close to the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable by
    // typical items -> penalize them heavily.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 6.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: leftover is dead space.
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: mildly discourage proliferation of open bins,
    // but only when there are already many.
    score += 1.5 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    // Mean residual coupling: prefer bins close to the mean residual
    // (keeps a balanced portfolio of gaps).
    score += 0.2 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: make it attractive only when the current item is
    // large relative to typical residual space (a poor fit elsewhere).
    if bin_residual == bin_capacity {
        if item_size as f64 > mean_residual + 15.0 {
            score -= 25.0;
        } else {
            score += 20.0;
        }
    }

    score
