pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post residual (perfect chain match).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: big bonus; near match: proportional bonus.
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize leaving a large unusable hole.
            score += 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Penalize dead space relative to mean residual: leaving a residual far
    // below the mean means this bin becomes an outlier of wasted space.
    let resid = post_residual as f64;
    if resid < mean_residual {
        score += 0.5 * (mean_residual - resid);
    } else {
        score -= 0.2 * (resid - mean_residual);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Early in the stream, allow opening new bins more freely to build a
    // diverse residual pool; late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if the current placement would
        // create large dead space elsewhere or stream is early.
        score -= 15.0 * (1.0 - progress);
        // Penalize opening a new bin when the item would fit reasonably
        // (post residual small) in an existing bin.
        score += 6.0 * (1.0 - resid / bin_capacity as f64);
    }

    // Prefer packing into bins that will end up nearly full.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize dead space: residuals too small for the smallest plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward if the next item fits exactly into the post-residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 2.0;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: when many bins are open, prefer consolidating into existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score -= 1.5 * pressure.min(6.0);

    // Time horizon: early in the stream, be more willing to open new bins (exploration);
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as the stream progresses.
        score += 10.0 + 30.0 * progress;
        // But allow a new bin if item is huge and would leave a very tight fit elsewhere.
        if item_size >= 70 {
            score -= 12.0 * progress;
        }
    } else {
        // Existing bin: reward more strongly later in the stream.
        score -= 8.0 * progress;
    }

    // Mean-residual coupling: if this bin is below average residual (already well-used),
    // favor finishing it off.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth progress coupling: penalize large residuals more later in stream
    let late = progress * progress;
    score += 25.0 * late * norm_pr * norm_pr * pr;

    // Reward tight fits via smooth cubic of fit ratio
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio * fit_ratio * (1.0 + progress);

    // Mean residual interaction: prefer bins whose residual deviates from mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev - 6.0 * dev;

    // Last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits post residual (smooth coupling)
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let chain = next_item_size as f64 / cap;
        score -= 12.0 * chain * (1.0 + progress);
    } else if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 8.0 * gap * gap;
    }

    // Mild penalty for spreading across many open bins early
    score += 2.0 * open_bins_count as f64 * (1.0 - progress) * norm_pr;

    // New-bin candidate: penalize opening new bins unless residual waste is huge
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress) - 10.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: divide capacity into 8 classes.
    let class = post_residual / (bin_capacity / 8).max(1);
    let class_bonus = match class {
        0 => -30.0, // near-perfect fill
        1 => -18.0,
        2 => -10.0,
        3 => -4.0,
        4 => 2.0,
        5 => 6.0,
        6 => 10.0,
        _ => 14.0,  // huge waste left behind
    };
    score += class_bonus;

    // Parity / modulo structure of the residual: small odd residuals are dead space.
    if post_residual > 0 && post_residual % 2 == 1 && post_residual < 20 {
        score += 8.0;
    }
    // Multiples of 5 and 10 are reusable by common item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does the leftover fit the next item (or a harmonic divisor of it)?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // chain placement possible
        } else {
            // penalize residuals that block the next item badly
            let gap = next_item_size - post_residual.min(next_item_size);
            score += (gap as f64) * 0.15;
            // if next item is small and residual is in a bad class, dead space likely
            if next_item_size <= 20 && post_residual < next_item_size {
                score += 6.0;
            }
        }
        // exact chain: post_residual equals next item -> perfect
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else {
        // last item: any residual is pure waste, prefer tightest
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate: only attractive if nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let desperation = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        score = cap - desperation - 15.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0).min(1.0);
        if next_item_size > 0 && next_item_size > bin_residual {
            score += 100.0; // never open a bin that can't take the next item either
        }
    }

    // Mild preference for compacting when mean residual is high (fragmentation risk).
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Anything below the smallest plausible item (1..100, but conservatively < 20)
    // is nearly wasted capacity; penalize it hard.
    if post_residual < 20 {
        score += 90.0 * (1.0 - (post_residual as f64) / 20.0);
    } else if post_residual < 35 {
        score += 15.0;
    }

    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space pressure grows with stream progression.
    let progress = step_index as f64 / total_items as f64;
    score += 25.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // Open-bins pressure: with many bins open, prefer filling existing ones.
    score += 3.0 * open_bins_count as f64 * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit the resulting gap, mild penalty for stranding.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Mean-residual coupling: penalize creating a residual far below the mean
    // (fragmenting relative to the fleet state).
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score += 0.15 * diff;
    }

    // New-bin candidate calibration: an empty bin has large post_residual,
    // which is naturally unattractive; add a mild constant bias so we only
    // open new bins when the resulting score beats poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / (bin_capacity as f64));
    }

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.5 * waste;
    }

    // Penalize large unusable residuals relative to mean residual.
    if (post_residual as f64) > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Reward tight fits (small post_residual) more aggressively.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slightly discourage new bins late in the stream when alternatives exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 5.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (nonlinear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize creating tiny dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 / (1.0 + slack);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty if this bin becomes stranded.
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins with high mean residual: encourage consolidation into fuller bins.
    if open_bins_count > 3 && (bin_residual as f64) < mean_residual {
        score -= 5.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Time horizon: early in stream, tolerate spreading (favor new bins for large items);
    // late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early or for large items, costly late.
        score -= (1.0 - progress) * 8.0;
        score += progress * 6.0;
        if item_size >= 60 {
            score -= 4.0;
        }
    } else {
        score -= progress * 4.0 * (1.0 - fit_ratio);
    }

    // Mild penalty for leaving large post-residual unused relative to item size.
    score += 0.05 * (post_residual as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: tight fits (small post_residual) are rewarded superlinearly,
    // large dead space penalized superlinearly, with strength growing over stream progress.
    let tightness = 1.0 - fit_ratio; // 1 = perfect fill
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 60.0 * tightness * tightness * (0.5 + progress_poly);

    // Penalize residual that is too small to plausibly fit a future item (dead space),
    // smoothly interpolated around the threshold region.
    let dead = if pr < next_item_size as f64 && next_item_size > 0 {
        (next_item_size as f64 - pr) / cap
    } else {
        0.0
    };
    score += 45.0 * dead * dead * (1.0 - 0.5 * progress_poly);

    // Last-chance bonus: smooth reward when this is nearly the only fitting bin.
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 30.0 * last_chance * last_chance * (0.3 + 0.7 * progress_poly);

    // Mild preference for bins deviating below the mean residual (keep balanced spread).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev - 4.0 * dev;

    // Late-stream pressure: favor filling existing bins rather than opening new ones.
    score += 25.0 * progress_poly * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "usable" residue classes (multiples of common item-size blocks) are favored.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus = -40.0; // perfect closure
    } else if pr % 10 == 0 {
        class_bonus = -12.0; // decile class: highly reusable
    } else if pr % 5 == 0 {
        class_bonus = -6.0;
    } else if pr < 10 {
        class_bonus = 15.0; // dead space: unusable sliver
    } else {
        class_bonus = 3.0;
    }
    score += class_bonus;

    // Compatibility with lookahead item via integer-division thresholds.
    if next_item_size > 0 {
        let fits_next = next_item_size <= pr;
        if fits_next {
            // reward proportional to how well next item divides the leftover
            let q = pr / next_item_size.max(1);
            let r = pr % next_item_size.max(1);
            score -= 10.0 + 8.0 * (q as f64).min(3.0) - 2.0 * (r as f64) / cap;
            if r == 0 {
                score -= 15.0; // next item exactly tiles the residual
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty unless
            // leftover is tiny anyway (dead space already penalized)
            if pr >= next_item_size * 2 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity and open bins are crowded (high mean residual).
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * (1.0 - item_size as f64 / cap) - 25.0 * crowding - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
    }

    // Prefer tighter existing bins: penalize bins with much more room than needed.
    score += 0.15 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Small nudge toward exact-capacity fraction classes of item size.
    let item_class = item_size % 20;
    let resid_class = bin_residual % 20;
    if item_class == resid_class {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A residual gap is "dead" if it cannot hold even the smallest plausible item.
    if post_residual > 0 {
        let min_gap = 10u32.min(bin_capacity);
        if post_residual < min_gap {
            score += 60.0 * (min_gap - post_residual) as f64;
        }
        // Penalize gaps that are small relative to typical item sizes (10..80 range),
        // scaled by stream progress (later in stream => tighter discipline).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let unusable_zone = 20u32; // gaps below 20 rarely useful
        if post_residual < unusable_zone {
            score += (unusable_zone - post_residual) as f64 * (25.0 + 35.0 * progress);
        }
        // Reward near-perfect fits strongly.
        if post_residual == 0 {
            score -= 40.0;
        } else if post_residual <= 5 {
            score -= 15.0;
        }
    }

    // Perfect-fit bonus when the NEXT item exactly fills the leftover gap.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 55.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the fit is mediocre.
    let open_pressure = open_bins_count as f64;
    let fit_quality = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 1.0 };
    score += open_pressure * (1.0 - fit_quality) * 4.0;

    // Discourage bins far below the mean residual (wasteful picks), mildly.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate handling: an empty bin is attractive only when the current item
    // is large and would leave a large, reusable gap elsewhere; otherwise keep bins tight.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are already open
        // (amortization) or when the item is big.
        let big_item_bonus = item_size as f64 / bin_capacity as f64;
        score += 18.0 - 10.0 * big_item_bonus;
        if open_bins_count > 0 {
            score += 6.0 * (open_bins_count as f64).ln();
        }
        // If no open bin fits well (this is the only fitting candidate), opening a new
        // bin is fine — reduce the penalty.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on post-residual (prefer tight fits aggressively)
    score = score * score / (bin_capacity as f64) + post_residual as f64 * 0.5;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // chain completion
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportionally for small slack after next item
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize large leftover dead space
            let dead = post_residual as f64;
            score += dead * 0.8;
        }
    }

    // Compare residual against mean residual: prefer bins with below-average residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it attractive only when it enables good future packing
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if next_item_size > 0 && next_item_size as f64 > item_size as f64 * 1.2 {
            // big item coming: opening fresh bin is reasonable
            score -= 250.0 * progress;
        } else {
            // default: discourage opening new bins when open bins fit
            score += 150.0 + 50.0 * (open_bins_count as f64);
        }
    }

    // Early stream: be more open to new bins to build structure
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 30.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize large dead space quadratically.
    if post_residual > 0 {
        score += 0.012 * (post_residual as f64).powi(2);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 14.0;
            // Extra reward when next item fills the bin completely after this one.
            if post_residual == next_item_size {
                score -= 12.0;
            }
        } else {
            // Penalize stranding residual too small for the next item.
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // New-bin candidate logic: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = if next_item_size > 0 { (post_residual as f64 - next_item_size as f64).abs() } else { 0.0 };
        // Opening a new bin is penalized more early on and when many bins are open.
        score += 20.0 + 15.0 * (1.0 - progress) + 1.5 * open_bins_count as f64;
        // But allow new bin when existing residuals are fragmented / mean residual low.
        score -= 0.05 * mean_residual;
        // Allow new bin when no open bin offers a good fit (post_residual already computed as item slack for empty bin).
        if fitting_bins_count <= 1 {
            score -= 18.0;
        }
        let _ = poor_fits;
    }

    // Mild pressure to fill bins with high residual when many bins are open.
    if bin_residual > bin_capacity / 2 && open_bins_count > 2 {
        score -= 0.02 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: minimize post residual, with a smooth non-linear penalty on tiny dead space
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: late in the stream, tighten residual preference quadratically
    let progress_coupling = progress * progress * (pr_norm * cap - mean_residual.abs());
    score += 0.3 * progress_coupling;

    // Non-linear reward for exactness of fit (post_residual near zero)
    score -= (1.0 - pr_norm).exp() * 2.0;

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Lookahead: penalize if next item cannot fit into post-residual
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.15 * gap * gap / cap;
        // Reward if next item fits snugly
        let snug = (pr - next_item_size as f64).abs();
        score -= 1.5 * (-snug / 10.0).exp();
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // New-bin candidate handling: make empty bin attractive only when fit is poor
    if bin_residual == bin_capacity {
        score = pr * (1.0 + 0.5 * pr_norm * pr_norm)
            + 12.0
            - 6.0 * (1.0 - item_size as f64 / cap).exp()
            - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual buckets by capacity fraction.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Dead-space penalty: leftovers in (0,10) are almost unusable (items >= 1 but
    // practically small fragments). Strongly penalize tiny-but-nonzero leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic reward: exact-fill and half-fill leftovers are ideal classes.
    if post_residual == 0 {
        score -= 30.0; // perfect fit
    } else if post_residual == bin_capacity / 2 {
        score -= 12.0;
    } else if post_residual == bin_capacity / 4 || post_residual == 3 * bin_capacity / 4 {
        score -= 6.0;
    }

    // Modulo-class coupling: does next_item_size divide/fit harmonically into post_residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= 15.0; // next item exactly consumes leftover
        } else if rem < 10 {
            score += 10.0; // leaves another dead sliver
        } else {
            score -= 3.0; // still decent
        }
    } else if next_item_size > 0 {
        // Next item cannot use this leftover: leftover is likely dead.
        score += 8.0 + frac * 20.0;
    }

    // Prefer tight fits: closeness of item to bin_residual.
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += tightness * 25.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of opening a new bin; grows with number of open bins and mean fragmentation.
        score = cap * 0.75
            + open_bins_count as f64 * 2.0
            + (mean_residual / cap) * 30.0
            + progress * 5.0;
        // If no open bin fits well, allow new bin to compete.
        if fitting_bins_count == 0 {
            score -= cap * 0.9;
        }
        // Early stream: opening bins is cheap/flexible.
        if progress < 0.1 {
            score -= 15.0;
        }
    }

    // Mild global pressure: when many bins are open with high mean residual,
    // encourage consolidation into existing bins.
    if bin_residual != bin_capacity {
        score -= (mean_residual - post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residuals that are too small to hold the smallest plausible item (<=10)
    // are pure waste; penalize them heavily with a superlinear term.
    if post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual <= 20 {
        // Small but potentially usable gaps: mild penalty proportional to tightness
        score += 6.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    } else {
        // Larger residual space is valuable; reward keeping big residuals
        score -= 0.05 * post_residual as f64;
    }

    // --- Reward exact / near-exact fits ---
    if post_residual == 0 {
        score -= 25.0; // perfect fill is ideal
    } else if post_residual <= 5 {
        score -= 10.0; // near-perfect fill
    }

    // --- Open-bins pressure: discourage spreading across many bins ---
    // When many bins are open, prefer bins with tighter fits (lower post_residual
    // already does this); add pressure to close bins rather than open new ones.
    let open_pressure = open_bins_count as f64 * 0.3;
    score += open_pressure * (1.0 - post_residual as f64 / bin_capacity as f64);

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- Lookahead: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0; // next item still fits: chain continues
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only if current placements would leave
        // big dead space; otherwise penalize opening new bins mildly.
        let mean_res = mean_residual;
        if post_residual > mean_res {
            score += 15.0; // new bin would be looser than average open bin
        } else {
            score -= 5.0; // fresh bin keeps large usable residual
        }
        // Late in the stream, avoid opening new bins for small gains
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // --- Mean residual alignment: prefer bins whose residual is below average
    // (tighter bins), encouraging consolidation.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Aggressive 2-step lookahead: strongly reward exact match of next item into post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0; // perfect chain fit
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 35.0; // next item fits almost perfectly
            } else {
                score -= 20.0 / (1.0 + slack / 20.0); // decaying lookahead bonus
            }
        } else {
            // Next item cannot fit here; penalize proportionally to the shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += 6.0 + shortfall * 0.25;
        }
    }

    // Compare post_residual against mean residual: prefer bins that tighten the mean.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening new bins when reasonable open bins exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But a new bin is attractive if it leaves room for the next item exactly.
        if next_item_size > 0 && bin_capacity == next_item_size + item_size {
            score -= 40.0;
        }
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can't hold a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Perfect chaining: post residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Global state coupling: many open bins with slack -> prefer filling existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    score += pressure * (open_bins_count as f64).ln().max(0.0) * 5.0;

    // Time horizon: early in stream, allow new bins more readily; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score += 25.0 * (1.0 - progress) - 15.0 * progress;
        // Opening a new bin is fine if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Prefer bins with smaller residual overall (best-fit flavor).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = pr / cap;

    // Base: penalize wasted space, quadratically so tight fits win strongly.
    let mut score = pr * (1.0 + fit_ratio * fit_ratio);

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, keep residuals flexible (penalize small residuals mildly),
    // late in the stream, prefer tight packing (reward small residuals).
    let flex = (1.0 - progress) * (1.0 - progress);
    score = score * (1.0 - 0.25 * flex * (1.0 - fit_ratio)) + 0.35 * flex * pr;

    // Lookahead coupling: reward bins whose post-residual can host the next item,
    // with a smooth polynomial in the gap between post_residual and next item.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            let tight = 1.0 - (gap / cap).min(1.0);
            score -= 6.0 * tight * tight;
        } else {
            // smooth penalty for near-miss residuals (unusable dead space)
            let miss = (-gap / cap).min(1.0);
            score += 4.0 * miss * miss * (1.0 - miss);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 0.1 * pr;
    }

    // Mild global pressure: more open bins relative to progress -> prefer reusing.
    let density = open_bins_count as f64 / (total_items as f64).max(1.0);
    score += 20.0 * density * fit_ratio;

    // New-bin candidate handling: only attractive when residuals are globally poor
    // or this bin is a genuinely bad fit.
    if bin_residual == bin_capacity {
        let mean_fit = (mean_residual / cap).clamp(0.0, 1.0);
        // smooth gate: new bin competitive only if mean residual is small (poor fits)
        let gate = 1.0 / (1.0 + (mean_fit * 12.0).exp());
        score = cap * (1.0 - 0.5 * gate) + 10.0 * (1.0 - gate) * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 60.0 * (10.0 - pr) / 10.0; // tiny dead space is worst
    } else if pr == 0.0 {
        score -= 40.0; // perfect fit: strongly reward
    } else if pr < 20.0 {
        score += 20.0 * (20.0 - pr) / 20.0; // moderately bad gap
    }

    // Reward filling bins tightly (high fill ratio).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Open-bins pressure: prefer compacting into existing bins when many are open.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 35.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 5.0; // post residual unusable for next item: slight penalty
    }

    // New-bin candidate: only attractive when current bins are quite full or very fragmented.
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score += 20.0; // base cost of opening a new bin
        score -= 30.0 * mean_fullness; // discount when open bins are nearly full
        if open_bins_count == 0 {
            score -= 50.0; // must open a bin
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
    }

    // Mild progression term: later in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: tiny post-residual is highly desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post-residual can host the next item,
    // especially with a snug fit; penalize leaving a gap that just misses it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // snug second-step fit preferred
            if slack <= 5.0 {
                score -= 150.0;
            } else {
                score -= 50.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // near-miss penalty: dead space that cannot host the next item
            let miss = (next_item_size - post_residual) as f64;
            score += 2.0 * miss.min(40.0);
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized so we prefer
    // reusing open bins unless they are genuinely poor fits. A new bin is
    // attractive when the item is large relative to capacity (little waste risk).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - post_residual as f64; // = 0 for empty bin base
        // large items open bins cheaply; small items should reuse existing bins
        score += (bin_capacity as f64 - item_size as f64) * 1.5;
        if fitting_bins_count <= 1 {
            score -= 80.0; // opening a bin beats wasting a last-chance bin? no: keep reuse
            score += 200.0; // actually prefer reuse when another bin fits
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0; // fresh bin can host next item too
        }
    }

    // Late in the stream, consolidation matters more: penalize spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Reward tight fits: the smaller the post-residual, the better.
    score -= (1.0 - post / cap) * 25.0;

    // Penalize dead space that no future item (min size 1) can use efficiently:
    // very small post-residuals are fine, mid-size leftovers are the worst.
    if post > 0.0 && post < 20.0 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack_after_next = post - nxt;
            if slack_after_next < 10.0 {
                score -= 18.0; // perfect chain
            } else {
                score -= 6.0 * (1.0 - slack_after_next / cap);
            }
        } else {
            score += 4.0; // next item won't fit here; mildly penalize
        }
    }

    // Last chance: only one bin can fit this item — strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins that are already relatively full (low residual).
    score += (residual / cap) * 8.0;

    // Global pressure: when many bins are open relative to progress, discourage
    // opening new bins; early in the stream, allow more exploration.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (progress * (total_items.max(1) as f64)).max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure scaling.
        score = cap * 0.9 + pressure * 10.0 + mean_residual * 0.3;
        // Late in the stream, opening new bins is more acceptable if mean
        // residuals are fragmented; early on, prefer packing into existing bins.
        score -= progress * 15.0;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 && mean_residual > cap * 0.5 {
            score += 20.0; // existing bins likely suffice; penalize new bin
        }
    }

    // Mean residual coupling: penalize placing into bins far from the mean
    // unless it creates a tight fit (encourages balanced consolidation).
    let dev = (residual - mean_residual).abs();
    score += dev * 0.05 * (1.0 - (1.0 - post / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post residual), with a convex penalty
    // that grows super-linearly for large wasted space.
    let mut score = pr + 30.0 * norm_pr * norm_pr;

    // Smooth non-linear coupling of post residual with stream progress:
    // late in the stream, dead space is more costly (fewer chances to fill it).
    let progress_coupling = norm_pr * (progress * progress * (3.0 - 2.0 * progress));
    score += 25.0 * progress_coupling * cap * 0.01;

    // Coupling with mean residual: if this bin's post residual deviates far
    // below the mean, it's a good consolidation; penalize divergence above mean.
    let mean_norm = mean_residual / cap;
    let deviation = norm_pr - mean_norm;
    score += 15.0 * deviation * deviation.abs();

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    // (smoothly scaled by how snug the fit is).
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving post residual that can host the next item,
    // penalize near-miss residuals just below next_item_size (smooth trough).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = pr - ns;
        if gap >= 0.0 {
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            // smooth quadratic near-miss penalty
            score += 8.0 * (gap / ns) * (gap / ns) * ns * 0.1;
        }
    }

    // Mild penalty for spreading across many open bins late in stream.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes capture "reusable" gap sizes.
    // Residuals that are multiples of common item sizes (or near-capacity fractions)
    // are more likely to be filled by future items.
    let cap = bin_capacity as f64;

    // Reward residuals in "friendly" modulo classes (multiples of 10, and small classes)
    let post = post_residual as u32;
    if post == 0 {
        // Perfect fit: strongly reward
        score -= 60.0;
    } else if post % 10 == 0 {
        score -= 12.0;
    } else if post % 5 == 0 {
        score -= 5.0;
    } else {
        // Odd dead space: penalize
        score += 4.0;
    }

    // Integer-division thresholds on post_residual: tiny gaps are dead space
    let q = post / 10; // coarse class of residual
    if post > 0 && post < 10 {
        score += 25.0; // unusable sliver
    } else if q == 1 {
        score += 6.0; // 10-19: barely usable
    }

    // Lookahead harmony: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0;
        } else if post >= next_item_size && (post - next_item_size) % 10 == 0 {
            score -= 20.0;
        } else if post >= next_item_size {
            score -= (post - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual; penalize proportionally to waste
            score += (next_item_size.saturating_sub(post)) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // existing residuals are poor. Penalize the fresh bin mildly so it wins
    // only against genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
    } else {
        // Tightness reward: bins with small residual relative to capacity are precious
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 10.0 * tightness;
    }

    // Mean residual coupling: prefer bins below mean residual (more filled)
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Stream progression: later in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tightness_proxy(bin_residual, bin_capacity);

    score
}

#[inline]
fn tightness_proxy(residual: u32, capacity: u32) -> f64 {
    1.0 - (residual as f64 / capacity as f64)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize post_residuals that are too small
    // for the minimum item size (unusable gaps).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // dead space: gap smaller than any item
        } else if post_residual <= 15 {
            score += 25.0; // nearly dead space
        } else {
            score -= 8.0; // usable residual is fine
        }
    } else {
        score -= 40.0; // perfect fill: zero residual is ideal
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            score += 15.0; // next item can't use this residual
        }
    }

    // Open-bin pressure: discourage spreading when many bins are open,
    // but relax pressure when this is the last fitting bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if fitting_bins_count <= 1 {
        score -= 45.0; // last chance: strongly favor using this bin over a new one
    } else {
        score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 6.0 * progress);
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            score += 30.0 + 10.0 * (open_bins_count as f64).sqrt(); // prefer existing bins
        }
    }

    // Slight nudge toward bins below the mean residual (keeps residuals balanced).
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is valuable dead-space avoidance.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // 2-step lookahead: if the NEXT item exactly fills the post_residual,
    // this placement chains perfectly — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportionally to how snug the chain is
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit in the leftover; leftover is likely dead space
            score += 15.0;
        }
    }

    // Compare against mean residual: placing into a bin whose residual is
    // much larger than average wastes capacity that other bins could use.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.3 * residual_gap;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize choosing a fresh empty bin unless the item is large and
    // current bins are relatively full (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // open new bin when item is big and existing bins are tight
        score -= 20.0 * fill_ratio * pressure;
        score += 10.0 * (1.0 - pressure);
        // early in the stream, opening bins is cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for leaving residual in a "dead zone" (1..9) that few items can use.
    if post_residual >= 1 && post_residual <= 9 {
        score += 12.0;
    }

    score
}
